// Entradas en serie:
//   $('Leer sesiones activas') -> filas estado=ACTIVO s_fecha=hoy
//   $('Leer autorizados')      -> todos los autorizados
const sesiones = $('Leer sesiones activas').all().map(i => i.json);
const autorizados = $('Leer autorizados').all().map(i => i.json);

const nombresSuc = {};
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const idx = par.indexOf(':');
  const cod = (idx >= 0 ? par.slice(0, idx) : par).trim().toUpperCase();
  const nom = (idx >= 0 ? par.slice(idx + 1) : '').trim();
  if (cod) nombresSuc[cod] = nom || cod;
});
const nombreDe = c => nombresSuc[String(c || '').trim().toUpperCase()] || String(c || '').trim().toUpperCase();

const activas = sesiones.filter(s => String(s.estado || '').trim().toUpperCase() === 'ACTIVO');
if (activas.length === 0) return [];

const porSuc = {};
for (const s of activas) {
  const suc = String(s.sucursal || 'COM').trim().toUpperCase();
  (porSuc[suc] = porSuc[suc] || []).push(s);
}

const lineaSesion = s =>
  `   • Guía *${s.guia || 's/guia'}*` +
  (s.transportista ? ` — ${s.transportista}` : '') +
  (s.phone ? ` (${s.phone})` : '');

let textoAdmin = '🔴 *SESIONES ACTIVAS SIN CERRAR*\n\n';
textoAdmin += `Al cierre del día *${$now.toFormat('dd/MM/yyyy')}* quedaron sesiones en estado ACTIVO:\n`;
for (const suc of Object.keys(porSuc).sort()) {
  textoAdmin += `\n🏢 *${nombreDe(suc)}* (${porSuc[suc].length}):\n`;
  textoAdmin += porSuc[suc].map(lineaSesion).join('\n') + '\n';
}
textoAdmin += `\n_Total: ${activas.length} sesión(es). Por favor coordinar el cierre._`;

const out = [];
for (const a of autorizados) {
  const tipo = String(a.tipo || '').trim().toUpperCase();
  const phone = String(a.phone || '').trim();
  if (!phone) continue;

  if (tipo === 'ADMIN') {
    out.push({ json: { phone, texto: textoAdmin, rol: 'ADMIN' } });
  } else if (tipo === 'CAJERO') {
    const suc = String(a.sucursal || '').trim().toUpperCase();
    const lista = porSuc[suc];
    if (lista && lista.length) {
      let t = '🔴 *SESIONES ACTIVAS SIN CERRAR*\n\n';
      t += `Sucursal *${nombreDe(suc)}* — *${$now.toFormat('dd/MM/yyyy')}*\n\n`;
      t += `Quedaron *${lista.length}* sesión(es) en estado ACTIVO:\n`;
      t += lista.map(lineaSesion).join('\n');
      t += `\n\n_Por favor cerrar las sesiones antes de finalizar el día._`;
      out.push({ json: { phone, texto: t, rol: 'CAJERO', sucursal: suc } });
    }
  }
}
return out;
